module TopModule (
    input  logic        clk,
    input  logic        reset,
    output logic [2:0]  ena,
    output logic [15:0] q
);

    logic [3:0] d0, d1, d2, d3;

    assign q = {d3, d2, d1, d0};

    assign ena[0] = (d0 == 4'd9);
    assign ena[1] = (d0 == 4'd9) && (d1 == 4'd9);
    assign ena[2] = (d0 == 4'd9) && (d1 == 4'd9) && (d2 == 4'd9);

    always_ff @(posedge clk) begin
        if (reset) begin
            d0 <= 4'd0;
            d1 <= 4'd0;
            d2 <= 4'd0;
            d3 <= 4'd0;
        end else begin
            if (d0 == 4'd9) begin
                d0 <= 4'd0;
                if (d1 == 4'd9) begin
                    d1 <= 4'd0;
                    if (d2 == 4'd9) begin
                        d2 <= 4'd0;
                        if (d3 == 4'd9) begin
                            d3 <= 4'd0;
                        end else begin
                            d3 <= d3 + 4'd1;
                        end
                    end else begin
                        d2 <= d2 + 4'd1;
                    end
                end else begin
                    d1 <= d1 + 4'd1;
                end
            end else begin
                d0 <= d0 + 4'd1;
            end
        end
    end

endmodule

