module tb_TopModule;
    logic        clk;
    logic        reset;
    logic [2:0]  ena;
    logic [15:0] q;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        @(posedge clk);
        @(posedge clk);
        reset = 0;

        // Check initial state after reset
        if (q !== 16'h0000 || ena !== 3'b000) begin
            $display("SELFTEST FAIL: Reset state incorrect. q=%h, ena=%b", q, ena);
            $finish;
        end

        // Run through a few cycles up to d0 = 9
        for (int i = 0; i < 9; i++) begin
            @(posedge clk);
        end
        // At this point q should be 0009, ena[0] should be 1
        if (q !== 16'h0009 || ena !== 3'b001) begin
            $display("SELFTEST FAIL: At 9, q=%h, ena=%b", q, ena);
            $finish;
        end

        // Next cycle should rollover d0 to 0 and increment d1 to 1 (q = 0010), ena[0] becomes 0
        @(posedge clk);
        if (q !== 16'h0010 || ena !== 3'b000) begin
            $display("SELFTEST FAIL: Rollover to 10, q=%h, ena=%b", q, ena);
            $finish;
        end

        // Test near tens/hundreds rollover. Let's fast-forward or simulate until 99
        // Better yet, force or just run cycles. To test 99 -> 100:
        // Instead of running 99 cycles, let's test by observing behavior or setting state if possible,
        // but since we can't force internal signals easily without hierarchical path:
        // dut.d0 = 9; dut.d1 = 9;
        // Let's use hierarchical assignment for faster test coverage of 99->100 and 999->1000.
        @(posedge clk);
        dut.d0 = 4'd9;
        dut.d1 = 4'd9;
        dut.d2 = 4'd0;
        dut.d3 = 4'd0;
        // ena should be 3'b011 (ena[0]=1, ena[1]=1)
        #1;
        if (ena !== 3'b011) begin
            $display("SELFTEST FAIL: ena at 99 incorrect: ena=%b", ena);
            $finish;
        end

        @(posedge clk);
        // should be 0100, ena should be 000
        #1;
        if (q !== 16'h0100 || ena !== 3'b000) begin
            $display("SELFTEST FAIL: Rollover from 99 to 100 failed: q=%h, ena=%b", q, ena);
            $finish;
        end

        // Test 999 -> 1000
        dut.d0 = 4'd9;
        dut.d1 = 4'd9;
        dut.d2 = 4'd9;
        dut.d3 = 4'd0;
        #1;
        if (ena !== 3'b111) begin
            $display("SELFTEST FAIL: ena at 999 incorrect: ena=%b", ena);
            $finish;
        end

        @(posedge clk);
        #1;
        if (q !== 16'h1000 || ena !== 3'b000) begin
            $display("SELFTEST FAIL: Rollover from 999 to 1000 failed: q=%h, ena=%b", q, ena);
            $finish;
        end

        // Test 9999 -> 0000
        dut.d0 = 4'd9;
        dut.d1 = 4'd9;
        dut.d2 = 4'd9;
        dut.d3 = 4'd9;
        #1;
        if (ena !== 3'b111) begin
            $display("SELFTEST FAIL: ena at 9999 incorrect: ena=%b", ena);
            $finish;
        end

        @(posedge clk);
        #1;
        if (q !== 16'h0000 || ena !== 3'b000) begin
            $display("SELFTEST FAIL: Rollover from 9999 to 0000 failed: q=%h, ena=%b", q, ena);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

